}

type Field struct {
	Type   string `yaml:"type" json:"type"`
	Name   string `yaml:"name" json:"name"`
	Nullable bool  `yaml:"nullable" json:"nullable"`
}

func getStructNameAndFields(filename string) (StructInfo, error) {
	file, err := os.ReadFile(filename)
	if err != nil {
		return StructInfo{}, fmt.Errorf("failed to read file: %w", err)
	}
	var info StructInfo
	err = yaml.Unmarshal(file, &info)
	if err != nil {
		return StructInfo{}, fmt.Errorf("failed to unmarshal YAML: %w", err)
	}
	return info, nil
}

func convertToAvroSchema(structInfo StructInfo) ([]byte, error) {
	schema := make([]byte, 0)
	for _, field := range structInfo.Fields {
		fieldDef := fmt.Sprintf("%s:%s%s", field.Type, field.Nullable? "null," : "", field.Name)
		schema = append(schema, []byte(fieldDef))
	}
	return schema, nil
}

func main() {
	filename := os.Args[1]
	structName := os.Args[2]

	info, err := getStructNameAndFields(filename)
	if err != nil {
		fmt.Printf("Error reading file: %v\n", err)
		os.Exit(1)
	}

	schema, err := convertToAvroSchema(info)
	if err != nil {
		fmt.Printf("Error generating Avro schema: %v\n", err)
